import {Mission,benchmark,N,LABELS,panelName,clamp} from './engine.js';
import {createScene} from './scene.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let mission=new Mission(),selected=11,timer=null,sound=false,repairAction='patch',bench=null,truth=null,toastTimer,audio;
const scene=createScene($('#scene'),i=>{selected=i;render()});
const pct=v=>Math.round(v*100)+'%',fmt=v=>v==null?'Offline':v.toFixed(3),time=v=>`${String(Math.floor(v/60)).padStart(2,'0')}:${String(Math.floor(v%60)).padStart(2,'0')}`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function safe(fn){return(...args)=>{try{return fn(...args)}catch(e){toast(e.message);return null}}}
function pause(){clearInterval(timer);timer=null;render()}
function step(){if(!mission.step()){pause();toast(mission.status==='blocked'?'Restore an available robot to continue.':'Inspection finished. Review the evidence and verify a repair.')}else{selected=mission.latest.panel;if(sound)playTone();render()}}
function run(){if(timer){pause();return}if(mission.revealed){toast('Reset the scenario to begin a new blind mission.');return}if(mission.count>=mission.config.budget){toast('Inspection budget is complete. Review diagnostics or reset.');return}step();if(mission.status==='running')timer=setInterval(safe(step),Number($('#speed').value));render()}
function reset(config=mission.config){clearInterval(timer);timer=null;mission=new Mission(config);truth=null;selected=11;$('#truth-results').innerHTML='';scene.reset();render()}
function route(){const id=location.hash.slice(1)||'mission';const valid=['mission','diagnostics','repairs','benchmark','method'].includes(id)?id:'mission';$$('.page').forEach(p=>p.classList.toggle('active',p.id===valid));$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+valid));render();requestAnimationFrame(drawCharts)}
window.addEventListener('hashchange',route);
function render(){scene.update(mission,selected);const seen=mission.policy.obs.filter(o=>o.length).length,suspects=mission.policy.beliefs.filter((b,i)=>mission.policy.obs[i].length&&b.risk>.65).length;
$('#mission-state').textContent=timer?'INSPECTION IN PROGRESS':({ready:'READY FOR INSPECTION',running:'INSPECTION PAUSED',complete:'INSPECTION COMPLETE',blocked:'CREW UNAVAILABLE',revealed:'TRUTH REVEALED'}[mission.status]||'READY');$('#measurement-count').innerHTML=`${mission.count} <small>/ ${mission.config.budget}</small>`;$('#budget-bar').max=mission.config.budget;$('#budget-bar').value=Math.min(mission.count,mission.config.budget);$('#mission-time').textContent=time(mission.time);$('#energy-used').innerHTML=`${mission.energy.toFixed(1)} <small>u</small>`;$('#coverage').innerHTML=`${Math.round(seen/N*100)}<small>%</small>`;$('#suspects').textContent=seen?String(suspects).padStart(2,'0'):'—';$('#active-robots').innerHTML=`0${mission.robots.filter(r=>r.online&&r.energy>=4).length}<small>/02</small>`;$('#run').innerHTML=timer?'Pause inspection <span>Ⅱ</span>':mission.count?'Resume inspection <span>▶</span>':'Start inspection <span>▶</span>';$('#scenario-label').textContent=mission.revealed?'TRUTH REVEALED':'SEALED SCENARIO';$('#run').disabled=mission.revealed||mission.count>=mission.config.budget;$('#step').disabled=$('#run').disabled;$('#inspect-selected').disabled=mission.revealed||mission.count>=mission.config.budget;$('#execute-repair').disabled=mission.revealed;$('#reveal').disabled=mission.revealed;
$('#panel-map').innerHTML=mission.policy.beliefs.map((b,i)=>{const seen=mission.policy.obs[i].length;return`<button class="panel-cell ${i===selected?'selected ':''}${seen?(b.risk>.65?'risk':b.risk<.25?'safe':'uncertain'):''}" data-panel="${i}" aria-label="Panel ${panelName(i)}, ${seen?'anomaly probability '+pct(b.risk):'unmeasured'}" aria-pressed="${i===selected}">${panelName(i)}</button>`}).join('');
const b=mission.policy.beliefs[selected],obs=mission.policy.obs[selected],last=obs.at(-1);$('#selected-summary').innerHTML=`<div>Panel ${panelName(selected)} <span> / ${obs.length?LABELS[b.type]+' · '+pct(b.confidence):'Awaiting first measurement'}</span></div><a class="text-button" href="#diagnostics">Examine</a>`;
$('#robots').innerHTML=mission.robots.map((r,i)=>`<div class="robot-card ${r.online?'':'offline'}"><div class="robot-top"><strong>${r.name}</strong><button class="outline" data-robot="${i}">${r.online?'Disable':'Restore'}</button></div><p class="robot-role">${r.online?r.role+' · Panel '+panelName(r.panel):'Offline · tasks reassigned'} · ${Math.round(r.energy)}% energy</p><div class="battery"><div style="width:${r.energy}%"></div></div></div>`).join('');$('#event-log').innerHTML=mission.logs.slice(0,10).map(l=>`<div class="event"><time>${time(l.time)}</time><p>${l.text}</p></div>`).join('');$('#panel-select').value=selected;$('#repair-panel').value=selected;$('#diagnostic-panel').textContent=panelName(selected);
$('#hypotheses').innerHTML=LABELS.map((label,i)=>`<div class="hypothesis"><div><span>${label}</span><span>${pct(b.p[i])}${!obs.length?' prior':''}</span></div><div class="prob-track"><i style="width:${b.p[i]*100}%;${i===0?'background:var(--green)':''}"></i></div></div>`).join('');$('#sensor-values').innerHTML=['Resonance shift','Damping','Temperature','Strain'].map((name,k)=>`<div><span>${name}</span><strong>${last?fmt(last.features[k]):'—'}</strong></div>`).join('');$('#history').innerHTML=obs.length?obs.slice().reverse().map(o=>`<tr><td>${time(o.at)}</td><td>${o.robot}</td>${o.features.map(f=>`<td>${fmt(f)}</td>`).join('')}</tr>`).join(''):'<tr><td colspan="6">No measurements for this panel yet.</td></tr>';
const recommended=b.risk<.35?'Re-inspect':b.type===1?'Tighten':b.type===2?'Bond patch':b.type===3?'Reinforce':'Re-inspect';$('#repair-context').innerHTML=`<div class="recommendation">Suggested action: <strong>${obs.length?recommended:'Collect a measurement'}</strong>. ${obs.length?'Based on the highest-probability diagnosis. Isolation stops growth; reducing load slows it.':'No evidence yet to justify a repair.'}</div><p class="muted">Panel ${panelName(selected)} · ${obs.length?LABELS[b.type]+' hypothesis ('+pct(b.confidence)+')':'Unmeasured: inspect before selecting an intervention.'}</p>`;$('#repair-history').classList.toggle('empty',!mission.repairs.length);$('#repair-history').innerHTML=mission.repairs.length?mission.repairs.map(r=>`<div class="repair-record"><strong>${panelName(r.panel)} · ${r.action}</strong><div>Anomaly: ${pct(r.before)} → ${pct(r.after)}</div><span>${r.result}</span></div>`).join(''):'No intervention yet. Inspect a panel, then choose a repair.';drawCharts();}
function chart(canvas){if(!canvas.clientWidth)return null;const dpr=Math.min(devicePixelRatio,2),w=canvas.clientWidth,h=Number(canvas.getAttribute('height'))/1;const logical=canvas.dataset.height?Number(canvas.dataset.height):h;canvas.dataset.height=logical;canvas.width=w*dpr;canvas.height=logical*dpr;canvas.style.height=logical+'px';const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,logical);ctx.strokeStyle='#28333f';ctx.lineWidth=1;for(let y=20;y<logical;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}return{ctx,w,h:logical}}
function drawCharts(){let c=chart($('#waveform'));const obs=mission.policy.obs[selected],o=obs.at(-1);if(c){const{ctx,w,h}=c;ctx.font='12px Manrope';ctx.fillStyle='#a2aab3';if(!o){ctx.fillText('Select a measured panel to inspect its response.',15,h/2)}else{ctx.beginPath();ctx.strokeStyle='#ff794c';ctx.lineWidth=1.7;const freq=10*(1-(o.features[0]??0)*.5),damp=2+(o.features[1]??0)*7;for(let x=0;x<w;x++){const t=x/w,y=h/2+Math.sin(t*freq*Math.PI*2)*Math.exp(-t*damp)*h*.42;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.fillText('0 ms',5,h-5);ctx.fillText('200 ms',w-60,h-5)}}c=chart($('#forecast'));if(c){const{ctx,w,h}=c,b=mission.policy.beliefs[selected];ctx.fillStyle='#a2aab3';ctx.font='12px Manrope';if(!obs.length){ctx.fillText('Collect evidence to estimate a severity trajectory.',15,h/2);return}const origin=b.severity,rate=mission.config.growth?.09*(b.type===3?1.5:1):0;const isolated=mission.repairs.some(r=>r.panel===selected&&r.action==='isolate');const load=mission.repairs.some(r=>r.panel===selected&&r.action==='unload')?.4:1;for(const offset of [-.14,0,.14]){ctx.beginPath();ctx.setLineDash(offset?[4,5]:[]);ctx.strokeStyle=offset?'#657484':'#ff794c';ctx.lineWidth=offset?1:2;for(let x=30;x<w-15;x++){const t=(x-30)/(w-45)*6,v=clamp(origin+(isolated?0:rate*load)*t+offset);const y=h-35-v*(h-60);x===30?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke()}ctx.setLineDash([]);ctx.fillText('Estimated severity',30,15);ctx.fillText('Now',30,h-10);ctx.fillText('+6 thermal cycles',w-125,h-10)}}
function playTone(){const o=mission.policy.obs[selected].at(-1);if(!o){toast('Measure a panel first.');return}audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=600*(1-(o.features[0]??0)*.5);gain.gain.setValueAtTime(.075,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.4);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.45)}
const options=Array.from({length:N},(_,i)=>`<option value="${i}">${panelName(i)}</option>`).join('');for(const el of [$('#panel-select'),$('#repair-panel'),$('[name=panel1]'),$('[name=panel2]')])el.innerHTML=options;$('[name=panel1]').value=11;$('[name=panel2]').value=22;
const actions=[['tighten','Tighten','Re-seat a loose fastener.'],['patch','Bond patch','Stabilise delamination.'],['brace','Reinforce','Brace a microcrack.'],['unload','Reduce load','Slow growth by 60%; damage remains.'],['isolate','Isolate','Stop growth; damage remains.'],['inspect','Re-inspect','One additional measurement.']];$('#repair-options').innerHTML=actions.map(([id,name,desc])=>`<button class="repair-option ${id===repairAction?'selected':''}" data-action="${id}" aria-pressed="${id===repairAction}"><strong>${name}</strong><span>${desc}</span></button>`).join('');
$('#panel-map').onclick=e=>{const b=e.target.closest('[data-panel]');if(b){selected=+b.dataset.panel;render()}};$('#robots').onclick=e=>{const b=e.target.closest('[data-robot]');if(b){mission.toggleRobot(+b.dataset.robot);render()}};$('#run').onclick=safe(run);$('#step').onclick=safe(()=>{pause();step()});$('#reset').onclick=()=>{reset();toast('Mission reset. Same hidden scenario and random seed.')};$('#speed').onchange=()=>{if(timer){clearInterval(timer);timer=setInterval(safe(step),+$('#speed').value)}};$('#sound').onclick=safe(()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';$('#sound').setAttribute('aria-pressed',sound);if(sound&&mission.latest)playTone()});$('#thermal-cycle').onclick=safe(()=>{if(mission.revealed)throw Error('Reset after truth reveal.');mission.cycle();render();toast('Thermal cycle applied. Re-inspect to detect any changes.')});$$('[data-view]').forEach(b=>b.onclick=()=>{$$('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));scene.setMode(b.dataset.view)});$('#reset-camera').onclick=()=>scene.reset();
$('#panel-select').onchange=e=>{selected=+e.target.value;render()};$('#repair-panel').onchange=e=>{selected=+e.target.value;render()};$('#inspect-selected').onclick=safe(()=>{pause();const r=mission.robots.find(r=>r.online&&r.energy>=4);mission.measure(selected,r);mission.log(`Manual targeted measurement at ${panelName(selected)}.`);render();toast('Measurement added to the diagnosis.')});$('#play-signal').onclick=safe(playTone);$('#repair-options').onclick=e=>{const b=e.target.closest('[data-action]');if(b){repairAction=b.dataset.action;$$('[data-action]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)})}};$('#execute-repair').onclick=safe(()=>{pause();const result=mission.repair(selected,repairAction);render();toast(result||'New inspection added.')});
$('#judge-open').onclick=()=>{pause();$('#judge-dialog').showModal()};$('#judge-close').onclick=()=>$('#judge-dialog').close();$('[name=noise]').oninput=e=>$('#noise-output').textContent=e.target.value;$('#judge-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p1=+f.get('panel1'),p2=+f.get('panel2'),t2=+f.get('type2');if(p1===p2&&t2){$('#judge-error').textContent='Choose two different panels.';return}const sensors=[f.has('vibration'),f.has('vibration'),f.has('temperature'),f.has('strain')];if(!sensors.some(Boolean)){$('#judge-error').textContent='Enable at least one sensor.';return}const defects=[{panel:p1,type:+f.get('type1'),severity:+f.get('severity1')}];if(t2)defects.push({panel:p2,type:t2,severity:+f.get('severity2')});reset({seed:+f.get('seed'),budget:+f.get('budget'),noise:+f.get('noise'),growth:f.get('growth')==='true',sensors,defects});$('#judge-error').textContent='';$('#judge-dialog').close();location.hash='mission';toast('Scenario sealed. Begin the blind inspection.')};
$('#tour').onclick=()=>$('#tour-dialog').showModal();$('#tour-close').onclick=()=>$('#tour-dialog').close();$('#tour-start').onclick=()=>$('#tour-dialog').close();
$('#run-benchmark').onclick=async()=>{const btn=$('#run-benchmark');btn.disabled=true;btn.textContent='Running experiment…';await new Promise(r=>requestAnimationFrame(()=>setTimeout(r,20)));try{bench=benchmark({trials:+$('#trial-count').value,budget:+$('#bench-budget').value,noise:+$('#bench-noise').value});$('#benchmark-results').className='';$('#benchmark-results').innerHTML=`<div class="comparison">${[['active','Active inspection'],['sequential','Sequential scan']].map(([k,title])=>{const r=bench[k];return`<div class="compare-card"><p class="eyebrow">${title.toUpperCase()}</p><div class="big-score">${pct(r.recall)}</div><p class="muted">Mean defect recall</p><dl><dt>False alarms / scenario</dt><dd>${r.fp.toFixed(2)}</dd><dt>Missed defects / scenario</dt><dd>${r.fn.toFixed(2)}</dd><dt>Mean coverage</dt><dd>${pct(r.coverage)}</dd><dt>Energy / scenario</dt><dd>${r.energy.toFixed(1)} u</dd><dt>Time / scenario</dt><dd>${r.time.toFixed(1)} s</dd><dt>Measurements / scenario</dt><dd>${r.measurements.toFixed(1)}</dd></dl></div>`}).join('')}</div><p class="result-note">${bench.trials} scenarios · ${bench.budget} measurements maximum · noise σ=${bench.noise}. Active recall is ${(100*(bench.active.recall-bench.sequential.recall)).toFixed(1)} percentage points ${bench.active.recall>=bench.sequential.recall?'higher':'lower'}. These synthetic experiments are not evidence of real spacecraft performance. Both policies share the same inference model. Changing inspection order assigns seeded noise draws to different panels.</p>`;$('#export-benchmark').disabled=false;toast('Benchmark complete. All results are available for export.')}catch(e){toast(e.message)}finally{btn.disabled=false;btn.textContent='Run comparison'}};
$('#reveal').onclick=()=>{pause();truth=mission.truth();const r=mission.evaluate();$('#truth-results').innerHTML=`<div class="truth-grid"><div class="truth-item"><strong>${r.tp}</strong><span>Correct detections</span></div><div class="truth-item"><strong>${r.fp}</strong><span>False alarms</span></div><div class="truth-item"><strong>${r.fn}</strong><span>Missed defects</span></div><div class="truth-item"><strong>${pct(r.recall)}</strong><span>Recall after any repairs</span></div></div><div class="table-wrap"><table><thead><tr><th>Panel</th><th>Actual state now</th><th>Severity</th><th>Prediction</th><th>Measured</th></tr></thead><tbody>${truth.map((w,i)=>`<tr><td>${panelName(i)}</td><td>${LABELS[w.type]}${w.isolated?' · isolated':''}</td><td>${pct(w.severity)}</td><td>${LABELS[mission.policy.beliefs[i].type]}</td><td>${mission.policy.obs[i].length?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div>`;render();toast('Truth revealed. Reset to start another blind test.')};
function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export').onclick=()=>download('echo-medic-mission.json',JSON.stringify({version:'1.0',model:'Synthetic Bayesian panel diagnostic simulator',...mission.snapshot(),...(truth?{groundTruth:truth}:{})},null,2),'application/json');$('#export-benchmark').onclick=()=>{if(!bench)return;const keys=['recall','fp','fn','energy','time','coverage','measurements'];let csv='strategy,seed,'+keys.join(',')+'\n';for(const k of ['active','sequential'])bench.raw[k].forEach((r,i)=>csv+=`${k},${i+1},${keys.map(x=>r[x]).join(',')}\n`);download('echo-medic-benchmark.csv',csv,'text/csv')};
window.addEventListener('resize',()=>requestAnimationFrame(drawCharts));
// Optional WebMCP: same read action as the visible mission summary.
if(document.modelContext?.registerTool){const controller=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'read_echo_medic_diagnostics',title:'Read orbital diagnostics',description:'Read observed mission state and diagnostic beliefs. Does not reveal hidden defects.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object');return{status:mission.status,measurements:mission.count,robots:mission.robots,beliefs:mission.policy.beliefs}}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
route();
